package api

import (
	"fmt"
	"net/http"
	"strconv"
	"strings"
)

// Словарь UI-DSL имеет версию, и клиенты здороваются ею. Сервер и клиенты
// обновляются порознь: контейнер обновили, Sema.app на маке остался
// прежним — и без версии он показывал бы заглушки или пустоту, не сказав
// почему. Веб-клиент приезжает вместе с сервером и всегда его ровесник;
// беда существует ровно для приложения, и это названная цена того, что
// оно остаётся.
//
// Правило номера: добавили тип или поле, которое старый клиент может
// пропустить без вреда, — поднимаем UIDictVersion; изменили форму так,
// что старый клиент нарисует неправду, — поднимаем и uiDictMin.
const (
	UIDictVersion = 31 // 31: подсветка строки после перехода — поле документа Document.Highlight (метка элемента: «f:<форма>-<поле>» у поля формы, «r:<ID>» у строки, «s:<ID>» у раздела; клиент раскрывает свёрнутый раздел и «Тонкую настройку», подводит строку к середине окна и подсвечивает её на пару секунд; метка приезжает только в ответе на переход, в адресе экрана её нет) — на ней стоят поиск по настройкам, переходы из замечаний Обзора и журнал настроек; и у section значение Style «stack» (формы-строки внутри одной карточкой — «Под рукой» на Обзоре); раздел, названный сборщиком раскрытым (Expanded), больше не сворачивается проходом collapseLong (результаты поиска) — старый клиент подсветки не сделает, а «stack» нарисует пятью рамками: вреда нет, uiDictMin прежний; 30: права чатов матрицей — клетка матрицы «na» (такого права у такого чата не бывает: не нажимается, причина в подсказке), Cell.Inherited (значение чужое: у темы группы это право группы), у строки матрицы капсулы, полоса уровня, вложенность Style «nested» и меню «···», а на телефоне матрица раскладывается строкой с чипами прав (у существующих матриц выдачи тоже) — старый клиент нарисует «na» пустой клеткой, а чужое значение — своим: веб-клиент приезжает вместе с сервером и этой беды не знает, uiDictMin прежний; 29: настройки канала и устройства раскрываются на месте — поле «checks» (несколько вариантов из списка чипами, «Источники»; у каждого чипа свой флажок «имя.вариант») и у строки Component.Expand (подпись раскрытия вместо «Подробнее»: «Настройки») — старый клиент нарисует «checks» текстовым полем, а раскрытие подпишет «Подробнее»: вреда нет, uiDictMin прежний; 28: подсвеченное пояснение над настройками — у text значение Style «callout» (жирное начало в Title, дальше Text; «Почта → Спам», «Общее»: «одинаково для всех ящиков») — старый клиент нарисует обычный абзац без подсветки: вреда нет, uiDictMin прежний; 27: таблица table для одинаковых строк с управлением в ячейках — список прямо в ячейке (Cell.Select, применяется сразу), капсулы строки рядом с названием, полоса уровня строки (Level), а на телефоне строка раскладывается карточкой с подписью колонки у каждой ячейки; роли моделей стали такой таблицей — старый клиент не нарисует список в ячейке и покажет строку роли без выбора (веб-клиент приезжает вместе с сервером и этой беды не знает): вреда нет, uiDictMin прежний; 26: экран сущности — раздел со Style «danger» («Опасное»: красная карточка, кнопки внутри видимы), поле «timespan» (окно «с … до …» двумя полями времени, уходит параметрами <имя>_from и <имя>_to), у поля Field.Disabled (серые варианты сегментов) и Field.More (редкое поле под «Ещё N полей» в той же форме), у полки «ждут вас» кнопки в заголовке и меню у строки — старый клиент нарисует «Опасное» обычным разделом, окно текстовым полем, отключённые варианты и «Ещё N полей» не отличит от обычных: вреда нет, uiDictMin прежний; 25: строки настройки — форма со Style «rows» (поля слева подпись и подсказка, справа один контрол), метка редкого Tier «rare» у компонента и поля, умолчание поля Field.Default и раздел «Тонкая настройка» (section со Style «fine», он же Collapsed + Lazy «rare») — старый клиент нарисует обычную форму и обычный ленивый раздел, умолчание не покажет: вреда нет, uiDictMin прежний; 24: колонка разделов настроек — вид панели (Document.PanelKind = "sections") и заголовок группы без адреса (PanelItem.Kind = "heading"); старый клиент нарисует колонку обычным списком, а заголовок — пустой строкой с названием: вреда нет; 23: правила сервера тремя колонками образцов patterns и цвет выбранного варианта сегментного переключателя (Field.Tones) — старый клиент колонок не нарисует, а переключатель покажет без цвета: вреда нет; 22: признак «это устройство отмечено своим» у документа (Document.OwnDevice) — старый клиент его не увидит и просто не сохранит снимок, вреда нет; 21: признак «снимок отличается от показанного» у документа (Document.SnapshotDiffers) — старый клиент его не увидит и просто не сделает второй, снимочный запрос, вреда нет; 20: признак «можно хранить на устройстве» у документа (Document.Storable) и «можно отложить до связи» у действия (Action.Deferrable) — старый клиент их не увидит и просто ничего не сохранит и не отложит, вреда нет; 19: число ждущих для значка приложения (Document.Wait) — старый клиент не пометит значок, вреда нет; 18: картинка в строке (Component.Image) — старый клиент её просто не нарисует, вреда нет; 17: раздел, догружаемый при раскрытии (Component.Lazy, SearchHint) — старый клиент увидит пустой свёрнутый раздел; 16: форму сохраняет нижняя полоса экрана (Component.Deferred) — клиент не рисует у такой формы своей кнопки; 15: внутренние вкладки раздела настроек (Document.Subtabs, ActiveSubtab) и счётчик у вкладки (Filter.Badge, Filter.Level); 14: рамка с чужим документом в песочнице (Component.Frame, FrameImages) — HTML письма; 13: нижняя полоса телефона (Document.PhoneTabs), хозяин в шапке меню (Document.Owner), слова для поиска по меню (Screen.Words); 12: у пункта меню вложенные пункты (Screen.Children в глубину) — группы настроек стали узлами; 11: 11: закреплённый пункт меню (Screen.Pinned); 10: 10: лента разговора и письмо — именное ожидание thinking, карточка дела toolcard, свёрнутая цепочка писем chain, класс чувствительности classpicker, выбор сущности карточками switcher; 9: таблица table с подписями колонок, ряд капсул chipset с хвостом «ещё N», шаг мастера step, обратный путь crumb; 8: матрица выдачи matrix с клетками; 7: полка «ждут вас» shelf и свёрнутая группа строк rowgroup; 6: плитка-показатель metric, плашка поломки alarm, строка чисел figs; 5: поле «segments» — сегментный переключатель в строке настройки; 4: у пункта панели глубина, вид и раскрытие (Depth, Kind, Open); 3: вложенность (Nested); 2: у Select — подпись (Label)
	uiDictMin     = 1  // 1: словарь до появления версии — клиенты без заголовка
	uiDictHeader  = "X-Sema-UI"
)

// clientDictionary — версия словаря у клиента. Без заголовка — 1: так
// говорят приложения, собранные до появления рукопожатия.
func clientDictionary(r *http.Request) int {
	v := strings.TrimSpace(r.Header.Get(uiDictHeader))
	if v == "" {
		return 1
	}
	n, err := strconv.Atoi(v)
	if err != nil || n < 0 {
		return 0
	}
	return n
}

// outdatedClient — экран «обновите клиент», если версии несовместимы, иначе
// nil. Экран собран из типов первой версии словаря (header, text, button):
// его должен нарисовать даже самый старый клиент.
func outdatedClient(r *http.Request) *Document {
	v := clientDictionary(r)
	if v >= uiDictMin && v <= UIDictVersion {
		return nil
	}
	what := "Пересоберите приложение: из папки app — ./bundle.sh && open .build/Sema.app."
	if v > UIDictVersion {
		what = "Обновите сервер Сёмы: он старше клиента и не знает новых экранов."
	}
	return &Document{
		Dictionary: UIDictVersion,
		Title:      "Обновите клиент",
		Heading:    "Клиент и сервер говорят на разных версиях словаря экранов",
		Components: []Component{
			{Type: "header", Text: "Обновите клиент"},
			{Type: "text", Text: fmt.Sprintf("Клиент понимает словарь версии %d, сервер собирает экраны на версии %d и принимает клиентов с %d по %d.", v, UIDictVersion, uiDictMin, UIDictVersion)},
			{Type: "text", Text: what},
			{Type: "text", Style: "secondary", Text: "Пока версии не сойдутся, экраны не отдаются: старый клиент нарисовал бы их неправильно и молча."},
		},
	}
}

// stampDictionary — версия словаря в документе и в заголовке ответа: по
// заголовку клиент узнаёт её ещё до разбора JSON.
func stampDictionary(w http.ResponseWriter, doc *Document) {
	doc.Dictionary = UIDictVersion
	w.Header().Set(uiDictHeader, strconv.Itoa(UIDictVersion))
}

// dictionaryTypes — типы из файла словаря клиента: «component x» и
// «field x», строки с «#» — пояснения.
func dictionaryTypes(text string) (components, fields map[string]bool) {
	components, fields = map[string]bool{}, map[string]bool{}
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		kind, name, ok := strings.Cut(line, " ")
		if !ok {
			continue
		}
		switch kind {
		case "component":
			components[strings.TrimSpace(name)] = true
		case "field":
			fields[strings.TrimSpace(name)] = true
		}
	}
	return
}

// usedTypes — типы компонентов и полей, встреченные в документе, вместе
// с вложенными разделами и шагами мастера.
func usedTypes(doc *Document) (components, fields map[string]bool) {
	components, fields = map[string]bool{}, map[string]bool{}
	var walk func(cs []Component)
	walk = func(cs []Component) {
		for _, c := range cs {
			components[c.Type] = true
			for _, f := range c.Fields {
				fields[f.Type] = true
			}
			walk(c.Children)
		}
	}
	walk(doc.Components)
	if doc.Wizard != nil {
		for _, st := range doc.Wizard.Steps {
			for _, f := range st.Fields {
				fields[f.Type] = true
			}
		}
	}
	return
}
